def solve(n):
    def inside(x,y): return x*x+y*y<=n*n
    result=[]
    for y in range(-n,n+1):
        line=''
        for x in range(-n,n+1):
            boundary=inside(x,y) and any(not inside(a,b) for a,b in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)))
            line+='*' if boundary else ' '
        result.append(line.rstrip())
    return result
